CREATE TABLE IF NOT EXISTS migrations (name text PRIMARY KEY, applied_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS malls (id text PRIMARY KEY, settings jsonb NOT NULL, revision integer NOT NULL DEFAULT 1, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS floors (id text PRIMARY KEY, name text NOT NULL, level integer NOT NULL UNIQUE CHECK(level>=0), layout text NOT NULL DEFAULT 'standard', sort_order integer NOT NULL DEFAULT 0, active boolean NOT NULL DEFAULT true, created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS slots (id text PRIMARY KEY,floor_id text NOT NULL REFERENCES floors(id),key text NOT NULL,label text NOT NULL,UNIQUE(floor_id,key));
CREATE TABLE IF NOT EXISTS shop_templates (key text PRIMARY KEY,name text NOT NULL,sale_point_count integer NOT NULL DEFAULT 6,glb_url text,display_point_schema jsonb NOT NULL DEFAULT '{}');
CREATE TABLE IF NOT EXISTS categories (id text PRIMARY KEY,name text NOT NULL,slug text NOT NULL UNIQUE,parent_id text REFERENCES categories(id),active boolean NOT NULL DEFAULT true,sort_order integer NOT NULL DEFAULT 0,deleted_at timestamptz);
CREATE TABLE IF NOT EXISTS shops (id text PRIMARY KEY,name text NOT NULL,slug text NOT NULL UNIQUE,tagline text NOT NULL DEFAULT '',category text NOT NULL DEFAULT '',floor_id text NOT NULL REFERENCES floors(id),slot_id text UNIQUE REFERENCES slots(id),template text NOT NULL REFERENCES shop_templates(key),color text NOT NULL,logo text NOT NULL DEFAULT '',active boolean NOT NULL DEFAULT false,deleted_at timestamptz,created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS products (id text PRIMARY KEY,shop_id text NOT NULL REFERENCES shops(id),category_id text REFERENCES categories(id),name text NOT NULL,slug text NOT NULL UNIQUE,description text NOT NULL DEFAULT '',price integer NOT NULL CHECK(price>0),currency text NOT NULL DEFAULT 'PKR',status text NOT NULL CHECK(status IN ('draft','active','archived')),gender text NOT NULL DEFAULT 'unisex',age_group text NOT NULL DEFAULT 'adult',display_group text NOT NULL DEFAULT 'rack',display_order integer NOT NULL DEFAULT 0,featured boolean NOT NULL DEFAULT false,image text NOT NULL DEFAULT '',deleted_at timestamptz,created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS product_variants (id text PRIMARY KEY,product_id text NOT NULL REFERENCES products(id),sku text NOT NULL UNIQUE,size text NOT NULL,color text NOT NULL,price_override integer CHECK(price_override>=0),stock integer NOT NULL CHECK(stock>=0),active boolean NOT NULL DEFAULT true,UNIQUE(product_id,size,color));
CREATE TABLE IF NOT EXISTS product_media (id text PRIMARY KEY,product_id text NOT NULL REFERENCES products(id),url text NOT NULL,variants jsonb NOT NULL DEFAULT '{}',sort_order integer NOT NULL DEFAULT 0,alt_text text NOT NULL DEFAULT '');
CREATE TABLE IF NOT EXISTS product_sales (id text PRIMARY KEY,product_id text NOT NULL REFERENCES products(id),price integer NOT NULL CHECK(price>0),starts_at timestamptz NOT NULL,ends_at timestamptz NOT NULL,pinned boolean NOT NULL DEFAULT false,active boolean NOT NULL DEFAULT true,CHECK(ends_at>starts_at),created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS customers (id text PRIMARY KEY,email text NOT NULL UNIQUE,name text NOT NULL,phone text NOT NULL DEFAULT '',password_hash text,created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS addresses (id text PRIMARY KEY,customer_id text NOT NULL REFERENCES customers(id),data jsonb NOT NULL,is_default boolean NOT NULL DEFAULT false);
CREATE TABLE IF NOT EXISTS admin_users (id text PRIMARY KEY,email text NOT NULL UNIQUE,name text NOT NULL,password_hash text NOT NULL,role text NOT NULL CHECK(role IN ('super_admin','manager','editor')),active boolean NOT NULL DEFAULT true,created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS sessions (token_hash text PRIMARY KEY,user_id text NOT NULL,kind text NOT NULL CHECK(kind IN ('admin','customer')),csrf text NOT NULL,expires_at timestamptz NOT NULL);
CREATE TABLE IF NOT EXISTS carts (id text PRIMARY KEY,customer_id text REFERENCES customers(id),created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS cart_items (id text PRIMARY KEY,cart_id text NOT NULL REFERENCES carts(id) ON DELETE CASCADE,variant_id text NOT NULL REFERENCES product_variants(id),quantity integer NOT NULL CHECK(quantity>0 AND quantity<=20),UNIQUE(cart_id,variant_id));
CREATE TABLE IF NOT EXISTS orders (id text PRIMARY KEY,number text NOT NULL UNIQUE,customer_id text NOT NULL REFERENCES customers(id),status text NOT NULL DEFAULT 'pending',payment_status text NOT NULL DEFAULT 'unpaid',payment_method text NOT NULL,email text NOT NULL,shipping_address jsonb NOT NULL,subtotal integer NOT NULL,shipping integer NOT NULL,tax integer NOT NULL,total integer NOT NULL,currency text NOT NULL DEFAULT 'PKR',notes text NOT NULL DEFAULT '',idempotency_key text NOT NULL UNIQUE,cart_id text NOT NULL,access_token_hash text NOT NULL,created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS order_items (id text PRIMARY KEY,order_id text NOT NULL REFERENCES orders(id),product_id text NOT NULL REFERENCES products(id),variant_id text NOT NULL REFERENCES product_variants(id),name_snapshot text NOT NULL,variant_snapshot text NOT NULL,price_snapshot integer NOT NULL,quantity integer NOT NULL);
CREATE TABLE IF NOT EXISTS payments (id text PRIMARY KEY,order_id text NOT NULL REFERENCES orders(id),provider text NOT NULL,provider_ref text UNIQUE,amount integer NOT NULL,status text NOT NULL DEFAULT 'pending');
CREATE TABLE IF NOT EXISTS payment_events (id text PRIMARY KEY,created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS wishlists (customer_id text NOT NULL REFERENCES customers(id),product_id text NOT NULL REFERENCES products(id),PRIMARY KEY(customer_id,product_id));
CREATE TABLE IF NOT EXISTS audit_logs (id text PRIMARY KEY,admin_user_id text NOT NULL REFERENCES admin_users(id),action text NOT NULL,entity text NOT NULL,entity_id text NOT NULL,diff jsonb NOT NULL DEFAULT '{}',created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS outbox (id text PRIMARY KEY,kind text NOT NULL,payload jsonb NOT NULL,status text NOT NULL DEFAULT 'pending',attempts integer NOT NULL DEFAULT 0,error text,created_at timestamptz NOT NULL DEFAULT now(),sent_at timestamptz);
CREATE INDEX IF NOT EXISTS product_shop_idx ON products(shop_id,status) WHERE deleted_at IS NULL;
CREATE INDEX IF NOT EXISTS sales_active_idx ON product_sales(product_id,starts_at,ends_at) WHERE active=true;
CREATE INDEX IF NOT EXISTS order_customer_idx ON orders(customer_id,created_at);
CREATE INDEX IF NOT EXISTS session_expiry_idx ON sessions(expires_at);
